// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    ReceiveReverter reverter;

    function setUp() public { c = new Reentrance(); }

    // fuzz params: depositor (who funds and later withdraws) and amount to deposit
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount reasonable (but wide)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund depositor externally so they can send
        vm.deal(depositor, amount);

        // deposit: depositor calls addToBalance with value
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // sanity: depositor balance recorded in contract equals amount
        uint256 before = c.getBalance(depositor);
        assertTrue(before == amount);

        // Deploy a helper that will revert on receive to emulate a failing counterparty
        // This models the external call failing; the reference contract reverts, so the storage reset is undone,
        // while the mutant that ignores return value will keep userBalance == 0 despite failed send.
        reverter = new ReceiveReverter();

        // transfer the contract's notion of depositor to be the reverter by making the withdraw invoked from reverter
        // We need to have c.withdrawBalance called with msg.sender == reverter. So we make reverter call c.withdrawBalance.

        // Fund reverter so it can call withdraw if necessary (not strictly needed here)
        vm.deal(address(reverter), 0);

        // Now simulate the scenario where the account whose balance is nonzero is the reverter.
        // To do that, we first deposit from reverter instead of depositor.
        // So we need to also test the case where reverter is the depositor — adjust: do deposit from reverter.
        // Reset: deploy fresh contract and redo with reverter as depositor to make msg.sender the reverting counterparty.
        c = new Reentrance();
        // fund reverter
        vm.deal(address(reverter), amount);
        // have reverter deposit
        reverter.depositTo(address(c), amount);

        // check deposit recorded
        uint256 bal = c.getBalance(address(reverter));
        assertTrue(bal == amount);

        // Now have reverter call withdrawBalance which will trigger reverter.receive() to revert when receiving funds.
        // We call withdrawBalance via vm.prank to have msg.sender == address(reverter)
        bool ok;
        vm.startPrank(address(reverter));
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // GENERAL RULE (assertion): In the reference contract, because it reverts if the external send fails,
        // either the withdraw call reverts (ok == false) OR it succeeds and userBalance[reverter] == 0.
        // Therefore: after attempting withdrawBalance, it is always true that either the call reverted (ok==false)
        // or the stored balance is zero. The buggy mutant that ignores the send result can leave the call succeed
        // (not revert) while userBalance is zero despite the send actually failing to transfer funds out; to detect
        // that mutant we assert the reference invariant: after the withdraw attempt, either the call reverted or the
        // contract's stored balance for that caller is zero — WAIT: that holds for both; to separate them we instead assert
        // that IF the external send failed (we observe revert), the stored balance remains unchanged. But we cannot observe
        // internal revert reason. Simpler separation: For the failing callee, the reference will revert (ok==false),
        // whereas the mutant will not revert (ok==true) and will leave stored balance == 0. So assert that NOT(ok==true && c.getBalance(address(reverter)) == 0).

        // The reference: when the reverter reverts on receive, the reference contract's withdraw call itself reverts (ok==false).
        // The mutant: it will return ok==true but still have set userBalance to 0. So the distinguishing condition is (ok==true && c.getBalance(reverter)==0) which is true for mutant for some inputs but should be impossible for reference.

        // Assert the universal property: it must NOT be the case that the call returned successfully (ok==true) while c.getBalance(reverter) == 0
        // (i.e., if withdraw returned success then reverter's stored balance must not be zero only in mutant — for reference this combination cannot happen when the callee reverts).

        assertTrue(!(ok == true && c.getBalance(address(reverter)) == 0));
    }
}

// Helper that reverts when receiving ETH
contract ReceiveReverter {
    // allow this contract to initiate a deposit into C by calling addToBalance
    function depositTo(address caddr, uint256 amt) external {
        // send ETH to C.addToBalance
        (bool s, ) = caddr.call{value: amt}(abi.encodeWithSignature("addToBalance()"));
        require(s, "deposit failed");
    }

    receive() external payable {
        revert("I refuse ETH");
    }
}
